-- # Every <predefined type> (6.1), other than JSON, can be the type of a
-- # column. Each one is described by the COLUMNS view of the INFORMATION_SCHEMA.
/* define every_type */
CREATE TABLE t (
  c01 CHARACTER(2), c02 CHARACTER VARYING(3), c03 CHARACTER LARGE OBJECT(4),
  c04 NATIONAL CHARACTER(5), c05 NATIONAL CHARACTER VARYING(6), c06 NATIONAL CHARACTER LARGE OBJECT,
  c07 BINARY(7), c08 BINARY VARYING(8), c09 BINARY LARGE OBJECT(9),
  c10 NUMERIC(5, 2), c11 DECIMAL(6, 1), c12 SMALLINT, c13 INTEGER, c14 BIGINT,
  c15 FLOAT(10), c16 REAL, c17 DOUBLE PRECISION, c18 DECFLOAT(16),
  c19 BOOLEAN, c20 DATE, c21 TIME(3) WITH TIME ZONE, c22 TIMESTAMP(0) WITHOUT TIME ZONE,
  c23 INTERVAL YEAR(3) TO MONTH, c24 INTERVAL DAY TO SECOND(4)
);

/* include every_type */
SELECT column_name, data_type, character_maximum_length, character_octet_length, numeric_precision, numeric_precision_radix, numeric_scale, datetime_precision, interval_type, interval_precision, character_set_name FROM information_schema.columns WHERE table_name = 'T' ORDER BY column_name;
