-- # Each type outside of Core SQL is flagged with its feature.
/* flags */
CREATE TABLE t (a CLOB, b NCHAR(2), c BINARY(3), d VARBINARY(4), e BLOB, f DECFLOAT, g INTERVAL DAY);
-- flags: F052, F421, T021, T045, T046, T076
-- msg: CREATE TABLE 1

/* flags */
VALUES X'01';
-- flags: F641, F661, T021
-- COL1: 01

/* flags */
VALUES N'a';
-- flags: F421, F641, F661
-- COL1: a

/* flags */
VALUES INTERVAL '1' DAY;
-- flags: F052, F641, F661
-- COL1: 1

-- # A binary string literal can continue after a newline, which is a compound
-- # binary literal (5.3, Syntax Rules, 5).
/* flags */
VALUES X'01'
  '02';
-- flags: F641, F661, T021, T023
-- COL1: 0102
